values.value:
{
  "ClubMembershipApplicant": {
    "required": [
      "fullName",
      "email",
      "birthDate",
      "personalId",
      "phone"
    ],
    "validators": {
      "email": [
        {
          "validator": "ValidateClubEmail",
          "message": "ClubMembership_err_clubEmail"
        }
      ]
    },
    "hideProgress": true,
    "navigationByChild": true
  },
  "ClubMembershipMembership": {
    "required": [
      "startDate"
    ],
    "if (not(familyMembers > 0))": {
      "hidden": [
        "familyNames"
      ]
    },
    "if (not(plan='premium'))": {
      "hidden": [
        "premiumWishes"
      ]
    },
    "hideProgress": true,
    "navigationByChild": true
  },
  "ClubMembershipPayment": {
    "if (not(method='bank'))": {
      "hidden": [
        "iban"
      ]
    },
    "ticked": [
      "acceptRules"
    ],
    "hideProgress": true,
    "navigationByChild": true
  },
  "ClubMembershipCompany": {
    "pageValidators": [
      {
        "validator": "ValidateCompanyPage",
        "message": "ClubMembership_err_companyPage"
      }
    ],
    "hideProgress": true,
    "navigationByChild": true
  },
  "ClubMembershipSummary": {
    "hideProgress": true,
    "navigationByChild": true
  }
}
